@forelse($assignments as $assignment)
@php($submission = $submissions->get($assignment->id))
<article class="task"><h3>{{ $loop->iteration }}. {{ $assignment->title }}</h3><p><span class="badge">{{ $assignment->platform }}</span><span class="badge">{{ $assignment->status }}</span></p><p>Diterima: {{ \Carbon\CarbonImmutable::parse($assignment->created_at, 'UTC')->setTimezone(config('workflow.timezone'))->format('d M Y H:i') }} · Tenggat: {{ \Carbon\CarbonImmutable::parse($assignment->due_at, 'UTC')->setTimezone(config('workflow.timezone'))->format('d M Y H:i') }}</p><p class="url">Postingan: {{ $assignment->target_url }}</p>
@if($submission)
<p>Revisi {{ $submission->revision }} · Dikirim {{ \Carbon\CarbonImmutable::parse($submission->created_at, 'UTC')->setTimezone(config('workflow.timezone'))->format('d M Y H:i') }} · {{ $submission->status }}</p>
<table class="data"><thead><tr><th>Akun</th><th>Aktivitas</th><th>Pelaksanaan</th></tr></thead><tbody>@foreach(json_decode($submission->reported_activities, true) ?? [] as $activity)<tr><td>{{ $activity['account_name'] ?? '-' }}<br>{{ $activity['identity'] ?? '-' }}</td><td>{{ $activity['activity'] ?? '-' }}</td><td>{{ isset($activity['performed_at']) ? \Carbon\CarbonImmutable::parse($activity['performed_at'])->setTimezone(config('workflow.timezone'))->format('d M Y H:i') : '-' }}</td></tr>@endforeach</tbody></table>
@if($submission->notes)<p class="notes">Catatan pengguna: {{ $submission->notes }}</p>@endif
